class FlabGate extends AudioWorkletProcessor {
  constructor(o) {
    super();
    this.p = Object.assign({ threshold: -45, attack: 2, release: 120, range: -60 }, (o.processorOptions || {}).params);
    this.port.onmessage = (e) => Object.assign(this.p, e.data);
    this.env = 0;
    this.gain = 0;
  }
  process(inputs, outputs) {
    const inp = inputs[0], out = outputs[0];
    if (!inp || !inp.length) { for (const y of out) y.fill(0); return true; }
    const n = out[0].length;
    const thr = Math.pow(10, this.p.threshold / 20);
    const floor = Math.pow(10, this.p.range / 20);
    const a = Math.exp(-1 / (Math.max(0.1, this.p.attack) * sampleRate / 1000));
    const r = Math.exp(-1 / (Math.max(1, this.p.release) * sampleRate / 1000));
    for (let i = 0; i < n; i++) {
      let peak = 0;
      for (let c = 0; c < inp.length; c++) peak = Math.max(peak, Math.abs(inp[c][i]));
      this.env = peak > this.env ? peak : this.env * 0.9995;
      const target = this.env >= thr ? 1 : floor;
      this.gain = target > this.gain ? target + (this.gain - target) * a : target + (this.gain - target) * r;
      for (let c = 0; c < out.length; c++) out[c][i] = (inp[c] || inp[0])[i] * this.gain;
    }
    return true;
  }
}
registerProcessor("flab-gate", FlabGate);
